'use client'

import { useRef } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'

interface AnimatedLightProps {
  color: string
  intensity: number
  radius: number
  speed: number
  phase: number
  yOffset?: number
}

function AnimatedLight({ color, intensity, radius, speed, phase, yOffset = 0 }: AnimatedLightProps) {
  const lightRef = useRef<THREE.PointLight>(null)

  useFrame(({ clock }) => {
    if (lightRef.current) {
      const t = clock.getElapsedTime() * speed + phase
      lightRef.current.position.x = Math.cos(t) * radius
      lightRef.current.position.z = Math.sin(t) * radius
      lightRef.current.position.y = yOffset + Math.sin(t * 0.5) * 0.5
    }
  })

  return (
    <pointLight
      ref={lightRef}
      color={color}
      intensity={intensity}
      distance={10}
      decay={2}
    />
  )
}

export function Lights() {
  return (
    <>
      <ambientLight intensity={0.1} />

      {/* Colorful orbiting lights */}
      <AnimatedLight color="#ff3366" intensity={15} radius={3} speed={0.5} phase={0} yOffset={0} />
      <AnimatedLight color="#3366ff" intensity={15} radius={3.5} speed={0.4} phase={Math.PI * 0.5} yOffset={0.5} />
      <AnimatedLight color="#33ff66" intensity={12} radius={3} speed={0.6} phase={Math.PI} yOffset={-0.3} />
      <AnimatedLight color="#ff6633" intensity={12} radius={4} speed={0.35} phase={Math.PI * 1.5} yOffset={0.2} />
      <AnimatedLight color="#9933ff" intensity={15} radius={2.5} speed={0.55} phase={Math.PI * 0.75} yOffset={-0.5} />
      <AnimatedLight color="#ffff33" intensity={10} radius={3.2} speed={0.45} phase={Math.PI * 1.25} yOffset={0.4} />
    </>
  )
}
