'use client'

import { useRef, useMemo, useEffect, useState } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'
import { SVGLoader } from 'three/examples/jsm/loaders/SVGLoader.js'

// Fallback Apple logo path if external SVG fails to load
const APPLE_SVG_PATH = `M 170.51172 0 C 161.88509 0.19996584 151.92578 5.2002583 145.07422 11.800781
C 138.82269 17.801269 133.75312 27.201803 135.25 36.300781
C 144.67662 37.000778 154.5124 32.050098 161.06445 25.349609
C 167.31598 18.949146 171.68655 9.5998829 170.51172 0 z
M 143.31055 42.099609 C 127.96614 42.099609 118.15078 51.050781 103.40625 51.050781
C 88.361747 51.050781 75.11652 42.601563 62.269531 42.601563
C 36.27556 42.901554 9 66.050571 9 103.75
C 9 155.84896 53.341878 215 78.835938 215
C 92.580373 215 101.16348 206.05078 118.40625 206.05078
C 136.04897 206.05078 142.22547 215 157.46875 215
C 185.5615 215 205.85742 158.3996 205.85742 158.3996
C 205.85742 158.3996 176.21354 146.49805 176.21289 113.19922
C 176.21224 84.99965 199.01367 72.101563 199.01367 72.101563
C 199.01367 72.101563 182.3549 48.652344 152.96289 43.152344
C 149.46467 42.450855 146.26565 42.099609 143.31055 42.099609 z`

export function AppleLogo() {
  const groupRef = useRef<THREE.Group>(null)
  const [geometry, setGeometry] = useState<THREE.ExtrudeGeometry | null>(null)

  useEffect(() => {
    // Parse the SVG path data directly
    const loader = new SVGLoader()
    const svgData = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 215 215">
      <path d="${APPLE_SVG_PATH}" fill="black"/>
    </svg>`

    const result = loader.parse(svgData)

    if (result.paths.length > 0) {
      const shapes: THREE.Shape[] = []

      result.paths.forEach((path) => {
        const pathShapes = SVGLoader.createShapes(path)
        shapes.push(...pathShapes)
      })

      if (shapes.length > 0) {
        const extrudeSettings = {
          depth: 20,
          bevelEnabled: true,
          bevelThickness: 2,
          bevelSize: 1.5,
          bevelOffset: 0,
          bevelSegments: 8,
        }

        const geo = new THREE.ExtrudeGeometry(shapes, extrudeSettings)
        geo.center()

        setGeometry(geo)
      }
    }
  }, [])

  // Create metallic material
  const material = useMemo(() => {
    return new THREE.MeshStandardMaterial({
      color: '#888888',
      metalness: 0.95,
      roughness: 0.05,
      envMapIntensity: 1.5,
    })
  }, [])

  // Rotation animation
  useFrame(({ clock }) => {
    if (groupRef.current) {
      groupRef.current.rotation.y = clock.getElapsedTime() * 0.3
      groupRef.current.rotation.x = Math.sin(clock.getElapsedTime() * 0.2) * 0.1
    }
  })

  if (!geometry) return null

  return (
    <group ref={groupRef} scale={0.02} rotation={[0, 0, Math.PI]}>
      <mesh geometry={geometry} material={material} />
    </group>
  )
}
